import { Pool } from 'pg';

const pool = new Pool();

export async function findUser(email: string) {
  const query = `
    SELECT id, email, display_name
    FROM users
    WHERE email = '${email}'
  `;
  const result = await pool.query(query);
  return result.rows[0] ?? null;
}

