type Result = { id: string; value: number };

async function loadResults(ids: string[]): Promise<Result[][]> {
  const groups: Result[][] = [];
  const shared: Result[] = [];

  for (const id of ids) {
    const response = await fetch(`/api/results/${id}`);
    if (!response.ok) {
      throw new Error(`Request failed: ${response.status}`);
    }
    const result: Result = await response.json();
    shared.push(result);
    groups.push(shared);
  }

  return groups;
}

