interface User {
  id: string;
}

interface UserRepository {
  save(user: User): Promise<void>;
}

async function handleUser(
  repository: UserRepository,
  user: User
): Promise<void> {
  try {
    repository.save(user);
  } catch (error) {
    console.error('Save failed', error);
  }
}
